#!/usr/bin/env bash
# S-087: the generator of the welcome demonstration frames (backlog/
# S-087-first-run-welcome.md, manager decision D3). It renders the frames
# of crates/ui/ui/welcome-frames.slint, which draws the hive with the same
# hex cell component the real hive uses, into crates/ui/resources/welcome/
# as frame-{lp,lc,dp,dc}-NN.png: sixteen frames per sequence, the hive at
# the pointer (lp, dp) and centred (lc, dc), in the light and dark token
# schemes. The window plays the sequence its platform shows.
#
# Every file in crates/ui/resources/welcome is generated by this script
# from the project's own components and design tokens under the repository
# licence (see README.md there). No frame asset may be committed without
# this generator.
#
# Bootstrap: the workspace builds only with the frame files present, so a
# missing frame is first written as a tiny placeholder and then replaced by
# the render below.
#
# Usage: scripts/gen-welcome-frames.sh
set -eu
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
RES="$ROOT/crates/ui/resources/welcome"
FAMILIES="lp lc dp dc"
FRAMES=16

mkdir -p "$RES"
# The sample image the scene draws (S-087 D6).
[ -f "$ROOT/tests/fixtures/images/welcome-sample.png" ] || bash "$ROOT/scripts/gen-welcome-sample.sh"

for family in $FAMILIES; do
  for i in $(seq 0 $((FRAMES - 1))); do
    f="$RES/frame-$family-$(printf '%02d' "$i").png"
    [ -f "$f" ] || magick -size 8x8 xc:none "$f"
  done
done

export CARGO_BUILD_JOBS="${CARGO_BUILD_JOBS:-2}"
(cd "$ROOT" && cargo build --quiet --release -p kawaro-ui --example welcome_frames) || exit 2
BIN="${CARGO_TARGET_DIR:-$ROOT/target}/release/examples/welcome_frames"

OUT="$(mktemp -d)"
inner() {
  unset DISPLAY XDG_ACTIVATION_TOKEN
  kwin_wayland --virtual --socket "$WAYLAND_DISPLAY" --width 1920 --height 1080 >"$OUT/kwin.log" 2>&1 &
  local cpid=$!
  for _ in $(seq 100); do [ -S "$XDG_RUNTIME_DIR/$WAYLAND_DISPLAY" ] && break; sleep 0.1; done
  if [ ! -S "$XDG_RUNTIME_DIR/$WAYLAND_DISPLAY" ]; then
    echo "private compositor did not start"; tail "$OUT/kwin.log"; kill $cpid 2>/dev/null; return 2
  fi
  sleep 1
  local fail=0 family
  for family in $FAMILIES; do
    if ! "$BIN" --family "$family" --out "$RES"; then
      echo "FAIL rendering family $family"; fail=1
    fi
  done
  # The frames are opaque flat art: a 128 colour palette keeps the whole
  # embedded set far under the 2 MB budget of AC2 (the palette form of PNG).
  local f
  for f in "$RES"/frame-*.png; do
    magick "$f" -colors 128 PNG8:"$f"
  done
  kill $cpid 2>/dev/null
  timeout 5 tail --pid=$cpid -f /dev/null || kill -9 $cpid 2>/dev/null
  return $fail
}

export -f inner
export BIN OUT RES FAMILIES FRAMES
SANDBOX="$(mktemp -d)"
RUNTIME="$(mktemp -d)"
chmod 700 "$RUNTIME"
# A private compositor in a throwaway session, like the snapshot tests:
# nothing here may touch the live desktop.
env -u WAYLAND_DISPLAY -u DISPLAY -u HYPRLAND_INSTANCE_SIGNATURE \
  -u XDG_CURRENT_DESKTOP -u XDG_SESSION_DESKTOP -u DESKTOP_SESSION \
  -u SWAYSOCK -u I3SOCK -u DBUS_SESSION_BUS_ADDRESS \
  HOME="$SANDBOX" XDG_CONFIG_HOME="$SANDBOX/.config" XDG_DATA_HOME="$SANDBOX/.local/share" \
  XDG_CACHE_HOME="$SANDBOX/.cache" XDG_STATE_HOME="$SANDBOX/.local/state" \
  XDG_RUNTIME_DIR="$RUNTIME" WAYLAND_DISPLAY=wayland-sbh-frames \
  dbus-run-session -- bash -c inner
status=$?
rm -rf "$SANDBOX" "$RUNTIME"

total=0
for family in $FAMILIES; do
  n=$(find "$RES" -name "frame-$family-*.png" | wc -l)
  total=$((total + n))
done
echo "welcome frames: $total files in $RES"
[ $status -eq 0 ] && echo "gen-welcome-frames: ok"
exit $status
